INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(3, 6, '_form', '<label> اسمك\n    [text* your-name autocomplete:name] </label>\n\n<label> بريدك الإلكتروني\n    [email* your-email autocomplete:email] </label>\n\n<label> الموضوع\n    [text* your-subject] </label>\n\n<label> رسالتك (اختياري)\n    [textarea your-message] </label>\n\n[submit \"إرسال\"]'),
(4, 6, '_mail', 'a:8:{s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:37:\"[_site_title] <azoozkkll@hotmail.com>\";s:4:\"body\";s:211:\"من: [your-name] [your-email]\nالموضوع: [your-subject]\n\nمحتوى الرسالة:\n[your-message]\n\n-- \nThis is a notification that a contact form was submitted on your website ([_site_title] [_site_url]).\";s:9:\"recipient\";s:19:\"[_site_admin_email]\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";i:0;s:13:\"exclude_blank\";i:0;}'),
(5, 6, '_mail_2', 'a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:37:\"[_site_title] <azoozkkll@hotmail.com>\";s:4:\"body\";s:233:\"محتوى الرسالة:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\";s:9:\"recipient\";s:12:\"[your-email]\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";i:0;s:13:\"exclude_blank\";i:0;}'),
(6, 6, '_messages', 'a:12:{s:12:\"mail_sent_ok\";s:55:\"شكراً لك. لقد تم الإرسال بنجاح.\";s:12:\"mail_sent_ng\";s:102:\"حدث خطأ أثناء محاولة إرسال رسالتك. يرجى المحاولة مجدداً.\";s:16:\"validation_error\";s:121:\"يوجد خطأ أو أكثر بأحد الحقول، يرجى التحقق ومن ثم المحاولة مرة أخرى.\";s:4:\"spam\";s:102:\"حدث خطأ أثناء محاولة إرسال رسالتك. يرجى المحاولة مجدداً.\";s:12:\"accept_terms\";s:101:\"يجب عليك الموافقة على الشروط والأحكام قبل إرسال رسالتك.\";s:16:\"invalid_required\";s:38:\"الرجاء ملء هذا الحقل.\";s:16:\"invalid_too_long\";s:32:\"This field has a too long input.\";s:17:\"invalid_too_short\";s:69:\"هذا الحقل يحتوي على مدخلات قصيرة جداً.\";s:13:\"upload_failed\";s:72:\"حدث خطأ غير معروف أثناء عملية رفع الملف.\";s:24:\"upload_file_type_invalid\";s:68:\"غير مسموح لك رفع الملفات من هذا النوع.\";s:21:\"upload_file_too_large\";s:52:\"الملف الذي تم رفعه كبير جدًا.\";s:23:\"upload_failed_php_error\";s:54:\"حدث خطأ أثناء عملية رفع الملف.\";}'),
